'use client';

import React from 'react';
import { DashboardProvider, useDashboard } from '../../context/DashboardContext';
import { Sidebar } from '../../components/Dashboard/Sidebar';
import { ContextSidebar } from '../../components/Dashboard/ContextSidebar';
import { NotificationCenter } from '../../components/Shared/NotificationCenter';
import { Menu, Layers } from 'lucide-react';
import { AVAILABLE_MODELS } from '../../constants';

function DashboardLayoutContent({ children }: { children: React.ReactNode }) {
  const {
    workspaces,
    currentWorkspaceId,
    setCurrentWorkspaceId,
    sessions,
    currentSessionId,
    setCurrentSessionId,
    createNewSession,
    deleteSession,
    renameSession,
    isSidebarOpen,
    setIsSidebarOpen,
    handleLogout,
    isDarkMode,
    toggleTheme,
    isContextOpen,
    setIsContextOpen,
    updateWorkspaceState,
    settings,
    isLoadingData
  } = useDashboard();

  if (isLoadingData) {
    return (
       <div className="flex h-screen w-full items-center justify-center bg-gray-50 dark:bg-charcoal-950 text-accent-500">
         <div className="flex flex-col items-center gap-4">
           <div className="w-10 h-10 border-4 border-charcoal-200 dark:border-charcoal-800 border-t-accent-500 rounded-full animate-spin"></div>
           <p className="text-charcoal-500 dark:text-charcoal-400 text-sm animate-pulse">Loading Workspace...</p>
         </div>
       </div>
    );
  }

  const currentWorkspace = workspaces.find(w => w.id === currentWorkspaceId);
  const currentSession = sessions.find(s => s.id === currentSessionId);
  const filteredSessions = sessions.filter(s => s.workspaceId === currentWorkspaceId);

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-charcoal-950 overflow-hidden text-slate-800 dark:text-slate-200 font-sans transition-colors duration-200">
      <Sidebar 
        workspaces={workspaces}
        currentWorkspaceId={currentWorkspaceId}
        onSelectWorkspace={setCurrentWorkspaceId}
        sessions={filteredSessions}
        currentSessionId={currentSessionId}
        onNewChat={createNewSession}
        onSelectSession={setCurrentSessionId}
        onDeleteSession={deleteSession}
        onRenameSession={renameSession}
        isOpen={isSidebarOpen}
        onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
        onLogout={handleLogout}
        isDarkMode={isDarkMode}
        onToggleTheme={toggleTheme}
      />

      <div className="flex-1 flex flex-col h-full relative min-w-0 transition-all duration-300">
        
        {/* Navbar */}
        <header className="h-16 border-b border-gray-200 dark:border-charcoal-800 flex items-center justify-between px-6 bg-white dark:bg-charcoal-950 shrink-0 transition-colors duration-200">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 text-charcoal-500 dark:text-charcoal-400 hover:bg-gray-100 dark:hover:bg-charcoal-800 hover:text-slate-900 dark:hover:text-slate-200 rounded-lg transition-colors"
            >
              <Menu size={20} />
            </button>
            <div className="flex flex-col">
              <span className="font-semibold text-slate-800 dark:text-slate-200 truncate max-w-[200px]">
                {currentSession?.title || 'Dashboard Home'}
              </span>
              <span className="text-[10px] text-charcoal-500 dark:text-charcoal-400 font-mono">
                 {AVAILABLE_MODELS.find(m => m.id === (currentSession?.modelId || settings.defaultModelId))?.name || 'Model Not Selected'}
              </span>
            </div>
          </div>
          
          <div className="flex items-center gap-2">
            <NotificationCenter />
            
            <div className="h-6 w-px bg-gray-200 dark:bg-charcoal-800 mx-2"></div>

            <button 
              onClick={() => setIsContextOpen(!isContextOpen)}
              className={`p-2 rounded-lg transition-colors flex items-center gap-2 text-sm font-medium ${isContextOpen ? 'bg-gray-100 dark:bg-charcoal-800 text-accent-600 dark:text-accent-400' : 'text-charcoal-500 dark:text-charcoal-400 hover:text-slate-900 dark:hover:text-slate-200'}`}
              title="Toggle Context Panel"
            >
              <Layers size={18} />
              <span className="hidden sm:inline">Context</span>
            </button>
          </div>
        </header>

        {/* Main Content Area */}
        <div className="flex-1 flex overflow-hidden relative">
          <div className="flex-1 flex flex-col min-w-0 bg-white dark:bg-charcoal-950">
            {children}
          </div>
        </div>
      </div>

      <ContextSidebar 
        isOpen={isContextOpen}
        contextItems={currentWorkspace?.contextItems || []}
        similarityThreshold={currentWorkspace?.similarityThreshold || 0.7}
        onUpdateThreshold={(val) => {
            if (currentWorkspace) {
                updateWorkspaceState({ ...currentWorkspace, similarityThreshold: val });
            }
        }}
        onRemoveItem={(id) => {
            if (currentWorkspace) {
                updateWorkspaceState({ 
                    ...currentWorkspace, 
                    contextItems: currentWorkspace.contextItems.filter(i => i.id !== id) 
                });
            }
        }}
        onToggleActive={(id) => {
            if (currentWorkspace) {
                updateWorkspaceState({ 
                    ...currentWorkspace, 
                    contextItems: currentWorkspace.contextItems.map(i => i.id === id ? { ...i, isActive: !i.isActive } : i) 
                });
            }
        }}
      />
    </div>
  );
}

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  return (
    <DashboardProvider>
      <DashboardLayoutContent>
        {children}
      </DashboardLayoutContent>
    </DashboardProvider>
  );
}
