'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { MockApi } from '../services/mockApiService';
import { AuthService } from '../services/authService';
import { 
  ChatSession, 
  Workspace, 
  ContextItem, 
  AppSettings, 
  Message, 
  Role, 
  Attachment 
} from '../types';
import { AVAILABLE_MODELS, DEFAULT_SYSTEM_INSTRUCTION } from '../constants';
import { streamChatResponse } from '../services/geminiService';

const SETTINGS_KEY = 'anything_llm_settings';

interface DashboardContextType {
  // Workspaces
  workspaces: Workspace[];
  currentWorkspaceId: string | null;
  setCurrentWorkspaceId: (id: string | null) => void;
  updateWorkspaceState: (updatedWs: Workspace) => void;
  
  // Sessions
  sessions: ChatSession[];
  currentSessionId: string | null;
  setCurrentSessionId: (id: string | null) => void;
  createNewSession: () => Promise<void>;
  deleteSession: (id: string, e: React.MouseEvent) => Promise<void>;
  renameSession: (id: string, newTitle: string) => Promise<void>;
  
  // Chat Actions
  handleSendMessage: (text: string, attachments: Attachment[]) => Promise<void>;
  isStreaming: boolean;
  streamingContent: string;
  
  // Layout/UI State
  isSidebarOpen: boolean;
  setIsSidebarOpen: (open: boolean) => void;
  isContextOpen: boolean;
  setIsContextOpen: (open: boolean) => void;
  isDarkMode: boolean;
  toggleTheme: () => void;
  isLoadingData: boolean;
  
  // Settings
  settings: AppSettings;
  setSettings: React.Dispatch<React.SetStateAction<AppSettings>>;
  
  // Auth
  handleLogout: () => void;
}

const DashboardContext = createContext<DashboardContextType | undefined>(undefined);

export const DashboardProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isContextOpen, setIsContextOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);
  
  // App State
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [currentWorkspaceId, setCurrentWorkspaceId] = useState<string | null>(null);
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [isLoadingData, setIsLoadingData] = useState(true);
  
  // Streaming state
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamingContent, setStreamingContent] = useState('');

  // Settings
  const [settings, setSettings] = useState<AppSettings>({
    defaultModelId: AVAILABLE_MODELS[0].id,
    systemInstruction: DEFAULT_SYSTEM_INSTRUCTION,
    temperature: 0.7
  });

  // Theme Toggle
  const toggleTheme = useCallback(() => {
    setIsDarkMode(prev => {
      const newVal = !prev;
      document.documentElement.classList.toggle('dark', newVal);
      return newVal;
    });
  }, []);

  useEffect(() => {
     if (document.documentElement.classList.contains('dark')) {
         setIsDarkMode(true);
     } else {
         setIsDarkMode(false);
     }
  }, []);

  // Load Initial Data
  useEffect(() => {
    const fetchData = async () => {
      setIsLoadingData(true);
      try {
        const [fetchedWorkspaces, fetchedSessions] = await Promise.all([
            MockApi.fetchWorkspaces(),
            MockApi.fetchSessions()
        ]);
        
        setWorkspaces(fetchedWorkspaces);
        setSessions(fetchedSessions);

        if (fetchedWorkspaces.length > 0) {
            const initialWsId = fetchedWorkspaces[0].id;
            setCurrentWorkspaceId(initialWsId);
            const wsSessions = fetchedSessions.filter(s => s.workspaceId === initialWsId);
            if (wsSessions.length > 0) {
                 const sorted = wsSessions.sort((a, b) => b.createdAt - a.createdAt);
                 setCurrentSessionId(sorted[0].id);
            }
        }
      } catch (err) {
        console.error("Failed to fetch data", err);
      } finally {
        setIsLoadingData(false);
      }
    };

    fetchData();
    
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedSettings) {
      setSettings(JSON.parse(savedSettings));
    }
  }, []); 

  useEffect(() => {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  const updateWorkspaceState = useCallback((updatedWs: Workspace) => {
      setWorkspaces(prev => prev.map(w => w.id === updatedWs.id ? updatedWs : w));
  }, []);

  const createNewSession = async () => {
    if (!currentWorkspaceId) return;
    const newSession: ChatSession = {
      id: uuidv4(),
      workspaceId: currentWorkspaceId,
      title: 'New Chat',
      messages: [],
      modelId: settings.defaultModelId,
      createdAt: Date.now(),
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    await MockApi.createSession(newSession);
  };

  const deleteSession = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessions(prev => prev.filter(s => s.id !== id));
    if (currentSessionId === id) {
      const remaining = sessions.filter(s => s.id !== id && s.workspaceId === currentWorkspaceId);
      if (remaining.length > 0) setCurrentSessionId(remaining[0].id);
      else setCurrentSessionId(null);
    }
    await MockApi.deleteSession(id);
  };

  const renameSession = async (id: string, newTitle: string) => {
    setSessions(prev => prev.map(s => s.id === id ? { ...s, title: newTitle } : s));
    await MockApi.renameSession(id, newTitle);
  };

  const updateSessionState = (updatedSession: ChatSession) => {
    setSessions(prev => {
        const filtered = prev.filter(s => s.id !== updatedSession.id);
        return [updatedSession, ...filtered];
    });
  };

  const handleSendMessage = async (text: string, attachments: Attachment[]) => {
    if (!currentWorkspaceId) return;

    const currentWorkspace = workspaces.find(w => w.id === currentWorkspaceId);
    let sessionToUse = sessions.find(s => s.id === currentSessionId);
    let isNewSession = false;

    if (!sessionToUse) {
       const newId = uuidv4();
       const newSession: ChatSession = {
        id: newId,
        workspaceId: currentWorkspaceId,
        title: text.slice(0, 30) || 'New Chat',
        messages: [],
        modelId: settings.defaultModelId,
        createdAt: Date.now(),
       };
       sessionToUse = newSession;
       isNewSession = true;
       setSessions(prev => [newSession, ...prev]);
       setCurrentSessionId(newId);
    }

    const session = sessionToUse!;
    const userMessage: Message = {
      id: uuidv4(),
      role: Role.USER,
      text: text,
      attachments: attachments,
      timestamp: Date.now()
    };

    const updatedSession = {
      ...session,
      title: session.messages.length === 0 ? (text.slice(0, 30) || 'New Chat') : session.title,
      messages: [...session.messages, userMessage]
    };
    
    updateSessionState(updatedSession);
    setIsStreaming(true);
    setStreamingContent('');

    if(isNewSession) await MockApi.createSession(updatedSession);
    else await MockApi.updateSession(updatedSession);

    try {
      const activeContext = (currentWorkspace?.contextItems || []).filter(item => item.isActive !== false);
      const wsSystemInstruction = currentWorkspace?.systemInstruction || settings.systemInstruction;
      const systemWithContext = `${wsSystemInstruction}\n\n[CONTEXT DOCUMENTS FROM WORKSPACE "${currentWorkspace?.title}"]: ${activeContext.map(i => i.name).join(', ')}`;

      const responseText = await streamChatResponse(
        session.modelId,
        updatedSession.messages,
        text,
        attachments,
        systemWithContext,
        (chunkText) => {
          setStreamingContent(chunkText);
        }
      );

      const botMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        text: responseText,
        timestamp: Date.now()
      };

      const finalSession = {
        ...updatedSession,
        messages: [...updatedSession.messages, botMessage]
      };
      updateSessionState(finalSession);
      await MockApi.updateSession(finalSession);

    } catch (error) {
      console.error("Chat error", error);
      const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        text: "System Error: Unable to reach inference endpoint. Please check your API Key.",
        timestamp: Date.now(),
        isError: true
      };
      const errorSession = {
        ...updatedSession,
        messages: [...updatedSession.messages, errorMessage]
      };
      updateSessionState(errorSession);
      await MockApi.updateSession(errorSession);
    } finally {
      setIsStreaming(false);
      setStreamingContent('');
    }
  };

  const handleLogout = () => {
    AuthService.logout();
  };

  return (
    <DashboardContext.Provider value={{
      workspaces,
      currentWorkspaceId,
      setCurrentWorkspaceId,
      updateWorkspaceState,
      sessions,
      currentSessionId,
      setCurrentSessionId,
      createNewSession,
      deleteSession,
      renameSession,
      handleSendMessage,
      isStreaming,
      streamingContent,
      isSidebarOpen,
      setIsSidebarOpen,
      isContextOpen,
      setIsContextOpen,
      isDarkMode,
      toggleTheme,
      isLoadingData,
      settings,
      setSettings,
      handleLogout
    }}>
      {children}
    </DashboardContext.Provider>
  );
};

export const useDashboard = () => {
  const context = useContext(DashboardContext);
  if (context === undefined) {
    throw new Error('useDashboard must be used within a DashboardProvider');
  }
  return context;
};
